/** SymPy's doctests and unit tests of this module with SymPy's printed results. Generated by tools/sympy-corpus/totests from the SymPy corpora; do not edit. */

import { describe, expect, it } from 'vitest';
import { BinomialDistribution, DieDistribution, ExponentialDistribution, NormalDistribution, PoissonDistribution, RandomSymbol, SingleContinuousPSpace, SingleDiscretePSpace, SingleFinitePSpace, Sym, add, cmoment, correlation, coskewness, covariance, entropy, factorialMoment, kurtosis, median, moment, mul, pow, rational, rel, simplify, skewness, smoment, symbols, variance } from '../../src';
import { sympyStr } from '../sympy-str';
import { equivalent } from '../sympy-equivalent';

describe("doctests of sympy.stats.rv_interface", () => {
  it("cmoment(X, 3)", () => {
    const X = new Sym('X');
    expect(sympyStr(cmoment(new RandomSymbol(X, new SingleFinitePSpace([X, new DieDistribution([rational(6)])])), rational(3)))).toBe('0');
  });
  it("cmoment(X, 2)", () => {
    const X = new Sym('X');
    expect(sympyStr(cmoment(new RandomSymbol(X, new SingleFinitePSpace([X, new DieDistribution([rational(6)])])), rational(2)))).toBe('35/12');
  });
  it("cmoment(X, 2) == variance(X)", () => {
    expect(sympyStr(rational(35, 12).equals(rational(35, 12)))).toBe('True');
  });
  it("correlation(X, X)", () => {
    const X = new Sym('X');
    const lambda = new Sym('lambda', { real: true, positive: true });
    expect(sympyStr(correlation(new RandomSymbol(X, new SingleContinuousPSpace([X, new ExponentialDistribution([lambda])])), new RandomSymbol(X, new SingleContinuousPSpace([X, new ExponentialDistribution([lambda])]))))).toBe('1');
  });
  it("correlation(X, Y)", () => {
    const [X, Y] = symbols('X Y');
    const lambda = new Sym('lambda', { real: true, positive: true });
    expect(sympyStr(correlation(new RandomSymbol(X, new SingleContinuousPSpace([X, new ExponentialDistribution([lambda])])), new RandomSymbol(Y, new SingleContinuousPSpace([Y, new ExponentialDistribution([lambda])]))))).toBe('0');
  });
  it("correlation(X, Y + rate*X)", () => {
    const [X, Y] = symbols('X Y');
    const lambda = new Sym('lambda', { real: true, positive: true });
    expect(equivalent(sympyStr(correlation(new RandomSymbol(X, new SingleContinuousPSpace([X, new ExponentialDistribution([lambda])])), add(mul(lambda, new RandomSymbol(X, new SingleContinuousPSpace([X, new ExponentialDistribution([lambda])]))), new RandomSymbol(Y, new SingleContinuousPSpace([Y, new ExponentialDistribution([lambda])]))))), '1/sqrt(1 + lambda**(-2))', [X, lambda, Y], { fn: 'correlation', input: 'X' })).toBe(true);
  });
  it("coskewness(X, Y, Y)", () => {
    const [X, Y] = symbols('X Y');
    const p = new Sym('p', { positive: true });
    expect(sympyStr(coskewness(new RandomSymbol(X, new SingleContinuousPSpace([X, new ExponentialDistribution([p])])), new RandomSymbol(Y, new SingleContinuousPSpace([Y, new ExponentialDistribution([mul(2, p)])])), new RandomSymbol(Y, new SingleContinuousPSpace([Y, new ExponentialDistribution([mul(2, p)])]))))).toBe('0');
  });
  it("coskewness(X, Y + X, Y + 2*X)", () => {
    const [X, Y] = symbols('X Y');
    const p = new Sym('p', { positive: true });
    expect(sympyStr(coskewness(new RandomSymbol(X, new SingleContinuousPSpace([X, new ExponentialDistribution([p])])), add(new RandomSymbol(X, new SingleContinuousPSpace([X, new ExponentialDistribution([p])])), new RandomSymbol(Y, new SingleContinuousPSpace([Y, new ExponentialDistribution([mul(2, p)])]))), add(mul(2, new RandomSymbol(X, new SingleContinuousPSpace([X, new ExponentialDistribution([p])]))), new RandomSymbol(Y, new SingleContinuousPSpace([Y, new ExponentialDistribution([mul(2, p)])])))))).toBe('16*sqrt(85)/85');
  });
  it("coskewness(X + 2*Y, Y + X, Y + 2*X, X > 3)", () => {
    const [Y, X] = symbols('Y X');
    const p = new Sym('p', { positive: true });
    expect(sympyStr(coskewness(add(mul(2, new RandomSymbol(Y, new SingleContinuousPSpace([Y, new ExponentialDistribution([mul(2, p)])]))), new RandomSymbol(X, new SingleContinuousPSpace([X, new ExponentialDistribution([p])]))), add(new RandomSymbol(X, new SingleContinuousPSpace([X, new ExponentialDistribution([p])])), new RandomSymbol(Y, new SingleContinuousPSpace([Y, new ExponentialDistribution([mul(2, p)])]))), add(mul(2, new RandomSymbol(X, new SingleContinuousPSpace([X, new ExponentialDistribution([p])]))), new RandomSymbol(Y, new SingleContinuousPSpace([Y, new ExponentialDistribution([mul(2, p)])]))), rel('Gt', new RandomSymbol(X, new SingleContinuousPSpace([X, new ExponentialDistribution([p])])), 3)))).toBe('9*sqrt(170)/85');
  });
  it("coskewness(Y, Y, Y) == skewness(Y)", () => {
    expect(sympyStr(rational(2).equals(rational(2)))).toBe('True');
  });
  it("coskewness(X, Y + p*X, Y + 2*p*X)", () => {
    const [X, Y] = symbols('X Y');
    const p = new Sym('p', { positive: true });
    expect(equivalent(sympyStr(coskewness(new RandomSymbol(X, new SingleContinuousPSpace([X, new ExponentialDistribution([p])])), add(mul(p, new RandomSymbol(X, new SingleContinuousPSpace([X, new ExponentialDistribution([p])]))), new RandomSymbol(Y, new SingleContinuousPSpace([Y, new ExponentialDistribution([mul(2, p)])]))), add(mul(2, p, new RandomSymbol(X, new SingleContinuousPSpace([X, new ExponentialDistribution([p])]))), new RandomSymbol(Y, new SingleContinuousPSpace([Y, new ExponentialDistribution([mul(2, p)])]))))), '4/(sqrt(1 + 1/(4*p**2))*sqrt(4 + 1/(4*p**2)))', [X, p, Y], { fn: 'coskewness', input: 'X' })).toBe(true);
  });
  it("covariance(X, X)", () => {
    const X = new Sym('X');
    const lambda = new Sym('lambda', { real: true, positive: true });
    expect(sympyStr(covariance(new RandomSymbol(X, new SingleContinuousPSpace([X, new ExponentialDistribution([lambda])])), new RandomSymbol(X, new SingleContinuousPSpace([X, new ExponentialDistribution([lambda])]))))).toBe('lambda**(-2)');
  });
  it("covariance(X, Y)", () => {
    const [X, Y] = symbols('X Y');
    const lambda = new Sym('lambda', { real: true, positive: true });
    expect(sympyStr(covariance(new RandomSymbol(X, new SingleContinuousPSpace([X, new ExponentialDistribution([lambda])])), new RandomSymbol(Y, new SingleContinuousPSpace([Y, new ExponentialDistribution([lambda])]))))).toBe('0');
  });
  it("covariance(X, Y + rate*X)", () => {
    const [X, Y] = symbols('X Y');
    const lambda = new Sym('lambda', { real: true, positive: true });
    expect(sympyStr(covariance(new RandomSymbol(X, new SingleContinuousPSpace([X, new ExponentialDistribution([lambda])])), add(mul(lambda, new RandomSymbol(X, new SingleContinuousPSpace([X, new ExponentialDistribution([lambda])]))), new RandomSymbol(Y, new SingleContinuousPSpace([Y, new ExponentialDistribution([lambda])])))))).toBe('1/lambda');
  });
  it("entropy(X)", () => {
    const X = new Sym('X');
    expect(sympyStr(entropy(new RandomSymbol(X, new SingleContinuousPSpace([X, new NormalDistribution([rational(0), rational(1)])]))))).toBe('log(2)/2 + 1/2 + log(pi)/2');
  });
  it("entropy(D)", () => {
    const D = new Sym('D');
    expect(sympyStr(entropy(new RandomSymbol(D, new SingleFinitePSpace([D, new DieDistribution([rational(4)])]))))).toBe('log(4)');
  });
  it("factorial_moment(X, 2)", () => {
    const [X, lamda] = symbols('X lamda');
    expect(sympyStr(factorialMoment(new RandomSymbol(X, new SingleDiscretePSpace([X, new PoissonDistribution([lamda])])), rational(2)))).toBe('lamda**2');
  });
  it("factorial_moment(Y, 2)", () => {
    const Y = new Sym('Y');
    expect(sympyStr(factorialMoment(new RandomSymbol(Y, new SingleFinitePSpace([Y, new BinomialDistribution([rational(2), rational(1, 2), rational(1), rational(0)])])), rational(2)))).toBe('1/2');
  });
  it("factorial_moment(Y, 2, Y > 1) # find factorial moment for Y > 1", () => {
    const Y = new Sym('Y');
    expect(sympyStr(factorialMoment(new RandomSymbol(Y, new SingleFinitePSpace([Y, new BinomialDistribution([rational(2), rational(1, 2), rational(1), rational(0)])])), rational(2), rel('Gt', new RandomSymbol(Y, new SingleFinitePSpace([Y, new BinomialDistribution([rational(2), rational(1, 2), rational(1), rational(0)])])), 1)))).toBe('2');
  });
  it("kurtosis(X)", () => {
    const X = new Sym('X');
    expect(sympyStr(kurtosis(new RandomSymbol(X, new SingleContinuousPSpace([X, new NormalDistribution([rational(0), rational(1)])]))))).toBe('3');
  });
  it("kurtosis(X, X > 0) # find kurtosis given X > 0", () => {
    const X = new Sym('X');
    expect(sympyStr(kurtosis(new RandomSymbol(X, new SingleContinuousPSpace([X, new NormalDistribution([rational(0), rational(1)])])), rel('Gt', new RandomSymbol(X, new SingleContinuousPSpace([X, new NormalDistribution([rational(0), rational(1)])])), 0)))).toBe('(-4/pi - 12/pi**2 + 3)/(1 - 2/pi)**2');
  });
  it("kurtosis(Y)", () => {
    const Y = new Sym('Y');
    const lamda = new Sym('lamda', { real: true, positive: true });
    expect(sympyStr(kurtosis(new RandomSymbol(Y, new SingleContinuousPSpace([Y, new ExponentialDistribution([lamda])]))))).toBe('9');
  });
  it("median(N)", () => {
    const N = new Sym('N');
    expect(sympyStr(median(new RandomSymbol(N, new SingleContinuousPSpace([N, new NormalDistribution([rational(3), rational(1)])]))))).toBe('{3}');
  });
  it("median(D)", () => {
    const D = new Sym('D');
    expect(sympyStr(median(new RandomSymbol(D, new SingleFinitePSpace([D, new DieDistribution([rational(6)])]))))).toBe('{3, 4}');
  });
  it("moment(X, 1, 6)", () => {
    const X = new Sym('X');
    expect(sympyStr(moment(new RandomSymbol(X, new SingleFinitePSpace([X, new DieDistribution([rational(6)])])), rational(1), rational(6)))).toBe('-5/2');
  });
  it("moment(X, 2)", () => {
    const X = new Sym('X');
    expect(sympyStr(moment(new RandomSymbol(X, new SingleFinitePSpace([X, new DieDistribution([rational(6)])])), rational(2)))).toBe('91/6');
  });
  it("moment(X, 1) == E(X)", () => {
    expect(sympyStr(rational(7, 2).equals(rational(7, 2)))).toBe('True');
  });
  it("skewness(X)", () => {
    const X = new Sym('X');
    expect(sympyStr(skewness(new RandomSymbol(X, new SingleContinuousPSpace([X, new NormalDistribution([rational(0), rational(1)])]))))).toBe('0');
  });
  it("skewness(X, X > 0) # find skewness given X > 0", () => {
    const X = new Sym('X');
    expect(sympyStr(skewness(new RandomSymbol(X, new SingleContinuousPSpace([X, new NormalDistribution([rational(0), rational(1)])])), rel('Gt', new RandomSymbol(X, new SingleContinuousPSpace([X, new NormalDistribution([rational(0), rational(1)])])), 0)))).toBe('(-sqrt(2)/sqrt(pi) + 4*sqrt(2)/pi**(3/2))/(1 - 2/pi)**(3/2)');
  });
  it("skewness(Y)", () => {
    const Y = new Sym('Y');
    const lambda = new Sym('lambda', { real: true, positive: true });
    expect(sympyStr(skewness(new RandomSymbol(Y, new SingleContinuousPSpace([Y, new ExponentialDistribution([lambda])]))))).toBe('2');
  });
  it("smoment(Y, 4)", () => {
    const Y = new Sym('Y');
    const lambda = new Sym('lambda', { positive: true, real: true });
    expect(sympyStr(smoment(new RandomSymbol(Y, new SingleContinuousPSpace([Y, new ExponentialDistribution([lambda])])), rational(4)))).toBe('9');
  });
  it("smoment(Y, 4) == smoment(3*Y, 4)", () => {
    expect(sympyStr(rational(9).equals(rational(9)))).toBe('True');
  });
  it("smoment(Y, 3) == skewness(Y)", () => {
    expect(sympyStr(rational(2).equals(rational(2)))).toBe('True');
  });
  it("simplify(std(B))", () => {
    const p = new Sym('p');
    expect(sympyStr(simplify(pow(add(mul(p, pow(add(1, mul(-1, p)), 2)), mul(pow(p, 2), add(1, mul(-1, p)))), rational(1, 2))))).toBe('sqrt(p*(1 - p))');
  });
  it("variance(2*X)", () => {
    const X = new Sym('X');
    expect(sympyStr(variance(mul(2, new RandomSymbol(X, new SingleFinitePSpace([X, new DieDistribution([rational(6)])])))))).toBe('35/3');
  });
  it("simplify(variance(B))", () => {
    const p = new Sym('p');
    expect(sympyStr(simplify(add(mul(p, pow(add(1, mul(-1, p)), 2)), mul(pow(p, 2), add(1, mul(-1, p))))))).toBe('p*(1 - p)');
  });
});
